import {CUSTOMERS} from './data.js';
const image=new Image();image.src=new URL('./assets/faces-v3.png',import.meta.url).href;export const portraitReady=()=>image.complete&&image.naturalWidth>0;
export function drawPortrait(ctx,c,x,y,width,height){ctx.fillStyle='#8f9a86';ctx.fillRect(x,y,width,height);if(portraitReady()){const i=c.portraitIndex??Math.max(0,CUSTOMERS.findIndex(v=>v.id===c.id))%6,sx=(i%3)*image.naturalWidth/3,sy=Math.floor(i/3)*image.naturalHeight/2;ctx.drawImage(image,sx,sy,image.naturalWidth/3,image.naturalHeight/2,x,y,width,height);}if(c.appearance==='glasses'){ctx.strokeStyle='#242d27';ctx.lineWidth=4;ctx.strokeRect(x+width*.19,y+height*.36,width*.24,height*.12);ctx.strokeRect(x+width*.53,y+height*.36,width*.24,height*.12);ctx.beginPath();ctx.moveTo(x+width*.43,y+height*.4);ctx.lineTo(x+width*.53,y+height*.4);ctx.stroke();}if(c.appearance==='cap'||c.appearance==='beanie'){ctx.fillStyle=c.appearance==='cap'?'#3d5146':'#33392e';ctx.beginPath();ctx.ellipse(x+width*.48,y+height*.17,width*.37,height*.16,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(x+width*.12,y+height*.16,width*.75,height*.055);}}
export function drawIdentity(ctx,c){ctx.fillStyle='#c2c5a4';ctx.fillRect(0,0,1024,768);ctx.fillStyle='#293c2a';ctx.font='bold 46px monospace';ctx.fillText('STATE IDENTIFICATION',40,65);drawPortrait(ctx,c,40,105,260,350);ctx.fillStyle='#1c3023';ctx.font='bold 44px sans-serif';ctx.fillText(c.name,337,155);ctx.font='33px sans-serif';for(const[line,i]of [[c.gender+' / '+c.height,0],['DOB '+c.birth,1],[c.badge,2],[c.address,3]])ctx.fillText(line,337,225+i*61,630);ctx.font='28px sans-serif';ctx.fillText(c.job,40,510);let x=42;const data=c.badge+':'+c.name;for(let i=0;i<110;i++){const width=(data.charCodeAt(i%data.length)+i)%3+1;ctx.fillRect(x,560,width*2,120);x+=width*2+3;}ctx.font='24px monospace';ctx.fillText(c.badge+' / OPTICAL RECORD',42,722);}
